seo.schema:
{
    "@context": "https://schema.org",
    "@graph": [
        {
            "@type": "LocalBusiness",
            "@id": "{website}/#localbusiness",
            "name": "{business}",
            "url": "{website}",
            "telephone": "{tel}",
            "image": "{lb_logo}",
            "description": "{business} connects {city_state} property owners with independent local plumbing providers for leaks, clogs, water heaters, and other plumbing needs, with fast local response.",
            "areaServed": {
                "@type": "City",
                "name": "{city}"
            },
            "priceRange": "$$",
            "openingHours": "Mo-Fr 08:00-18:00, Sa 09:00-13:00"
        },
        {
            "@type": "WebSite",
            "@id": "{website}/#website",
            "url": "{website}",
            "name": "{business}",
            "publisher": {
                "@id": "{website}/#localbusiness"
            }
        }
    ]
}

{
    "@context": "https://schema.org",
    "@graph": [
        {
            "@type": "ContactPage",
            "@id": "{website}/contact-us/#contactpage",
            "url": "{website}/contact-us/",
            "name": "Contact {business}",
            "description": "Call or email {business} to be connected with a local plumbing provider in {city_state}.",
            "isPartOf": {
                "@id": "{website}/#website"
            },
            "about": {
                "@id": "{website}/#localbusiness"
            }
        },
        {
            "@type": "LocalBusiness",
            "@id": "{website}/#localbusiness",
            "name": "{business}",
            "url": "{website}",
            "telephone": "{tel}",
            "email": "{email}",
            "areaServed": {
                "@type": "City",
                "name": "{city}"
            },
            "contactPoint": {
                "@type": "ContactPoint",
                "telephone": "{tel}",
                "email": "{email}",
                "contactType": "customer service",
                "areaServed": "US",
                "availableLanguage": "English"
            }
        }
    ]
}

{
    "@context": "https://schema.org",
    "@graph": [
        {
            "@type": "AboutPage",
            "@id": "{website}/about-us/#aboutpage",
            "url": "{website}/about-us/",
            "name": "About {business}",
            "description": "How {business} connects {city_state} property owners with independent local plumbing providers.",
            "isPartOf": {
                "@id": "{website}/#website"
            },
            "about": {
                "@id": "{website}/#localbusiness"
            }
        },
        {
            "@type": "LocalBusiness",
            "@id": "{website}/#localbusiness",
            "name": "{business}",
            "url": "{website}",
            "telephone": "{tel}",
            "areaServed": {
                "@type": "City",
                "name": "{city}"
            }
        }
    ]
}
